import { z } from 'zod'
import { generateSchedule, type ScheduledInvoice } from '@/lib/billing'
import { badRequest, forbidden, notFound, withRetry } from '@/lib/errors'
import { prisma } from '@/lib/prisma'
import { loadCaller, requireLeaseAccess, requireMember } from '@/server/access'
import {
  compareAllocationOrder,
  isoDateToDb,
  paidByInvoice,
  serializeInvoice,
  serializeLease,
  serializePayment,
  type InvoiceDto,
  type LeaseDto,
  type PaymentDto,
  type ServiceCtx,
} from './serialize'

const ISO_DATE = /^\d{4}-\d{2}-\d{2}$/

const createLeaseSchema = z
  .object({
    unitId: z.string().uuid(),
    tenantId: z.string().uuid(),
    startDate: z.string().regex(ISO_DATE, 'must be YYYY-MM-DD'),
    endDate: z.string().regex(ISO_DATE, 'must be YYYY-MM-DD'),
    monthlyRentSen: z.number().int().positive(),
    depositSen: z.number().int().nonnegative(),
  })
  .strict()

export type CreateLeaseInput = z.infer<typeof createLeaseSchema>

// D2 order for POST /api/leases: the route calls this before reading the body, so a non-manager gets 403
// even when the body is malformed JSON. createLease repeats the check, so it is safe to call alone.
export async function requireLeaseCreator(ctx: ServiceCtx): Promise<void> {
  requireMember(await loadCaller(ctx.userId), ['manager'])
}

export async function createLease(ctx: ServiceCtx, input: unknown): Promise<{ id: string }> {
  const caller = await loadCaller(ctx.userId)
  // POST /api/leases has no target record yet, so the role check (403) precedes body validation (400).
  const { orgId } = requireMember(caller, ['manager'])
  const body = createLeaseSchema.parse(input)

  // R11/R46: the schedule comes only from billing.ts; its validation errors are the 400 message.
  let schedule: ScheduledInvoice[]
  try {
    schedule = generateSchedule(body)
  } catch (e) {
    throw badRequest(e instanceof Error ? e.message : 'Invalid lease')
  }

  // R39/D15: body ids are untrusted; a unit or tenant outside the caller's org is a 404, exactly like a
  // nonexistent one, so another org's ids are never confirmed. The composite FKs enforce the same in the DB.
  const [unit, tenant] = await Promise.all([
    prisma.units.findFirst({ where: { id: body.unitId, org_id: orgId }, select: { id: true } }),
    prisma.tenants.findFirst({ where: { id: body.tenantId, org_id: orgId }, select: { id: true } }),
  ])
  if (!unit) throw notFound('Unit not found')
  if (!tenant) throw notFound('Tenant not found')

  // R46: lease + exactly the scheduled invoices + audit row commit together or not at all. Overlap is
  // enforced by the leases_no_overlap EXCLUDE constraint (D16): a concurrent overlapping insert waits,
  // then fails with 23P01, which errors.ts maps to 409. withRetry covers a deadlock (40P01) once.
  return withRetry(() =>
    prisma.$transaction(async (tx) => {
      const lease = await tx.leases.create({
        data: {
          org_id: orgId,
          unit_id: body.unitId,
          tenant_id: body.tenantId,
          start_date: isoDateToDb(body.startDate),
          end_date: isoDateToDb(body.endDate),
          monthly_rent_sen: body.monthlyRentSen,
          deposit_sen: body.depositSen,
          created_by: caller.userId,
        },
        select: { id: true },
      })
      await tx.invoices.createMany({
        data: schedule.map((inv) => ({
          org_id: orgId,
          lease_id: lease.id,
          kind: inv.kind,
          period_index: inv.periodIndex,
          period_start: inv.periodStart === null ? null : isoDateToDb(inv.periodStart),
          period_end: inv.periodEnd === null ? null : isoDateToDb(inv.periodEnd),
          due_date: isoDateToDb(inv.dueDate),
          amount_sen: inv.amountSen,
        })),
      })
      await tx.audit_log.create({
        data: {
          org_id: orgId,
          actor_id: caller.userId,
          action: 'lease.created',
          entity_id: lease.id,
          details: {
            unitId: body.unitId,
            tenantId: body.tenantId,
            startDate: body.startDate,
            endDate: body.endDate,
            monthlyRentSen: body.monthlyRentSen,
            depositSen: body.depositSen,
            invoiceCount: schedule.length,
          },
        },
      })
      return { id: lease.id }
    }),
  )
}

export type LeaseDetail = { lease: LeaseDto; invoices: InvoiceDto[]; payments: PaymentDto[] }

// GET /api/leases/:leaseId, the brief's shape exactly. asOf drives the overdue status (R17).
export async function getLease(ctx: ServiceCtx, leaseId: string, asOf: Date = new Date()): Promise<LeaseDetail> {
  const caller = await loadCaller(ctx.userId)
  const lease = await requireLeaseAccess(caller, leaseId, ['manager', 'staff', 'tenant'])
  // Every query is scoped by the checked lease's own org_id as well as its id (D18).
  const scope = { lease_id: lease.id, org_id: lease.org_id }
  const [invoiceRows, allocationSums, paymentRows] = await Promise.all([
    prisma.invoices.findMany({ where: scope }),
    prisma.payment_allocations.groupBy({ by: ['invoice_id'], where: scope, _sum: { amount_sen: true } }),
    prisma.payments.findMany({ where: scope, orderBy: [{ received_at: 'asc' }, { created_at: 'asc' }, { id: 'asc' }] }),
  ])
  // Voiding deletes that payment's allocations (D14), so every remaining allocation counts as paid.
  const paid = paidByInvoice(allocationSums)
  const invoices = invoiceRows.map((row) => serializeInvoice(row, paid.get(row.id) ?? 0, asOf)).sort(compareAllocationOrder)
  return { lease: serializeLease(lease), invoices, payments: paymentRows.map(serializePayment) }
}

export type LeaseListItem = LeaseDto & { unitName: string; tenantName: string }

// Leases list for the UI: staff/manager see their org's leases; a tenant sees only their own.
export async function listLeases(ctx: ServiceCtx): Promise<LeaseListItem[]> {
  const caller = await loadCaller(ctx.userId)
  const or: ({ org_id: string } | { tenant_id: { in: string[] } })[] = []
  if (caller.member) or.push({ org_id: caller.member.orgId })
  if (caller.tenantIds.length > 0) or.push({ tenant_id: { in: caller.tenantIds } })
  if (or.length === 0) throw forbidden()
  const rows = await prisma.leases.findMany({
    where: { OR: or },
    include: { units: { select: { name: true } }, tenants: { select: { full_name: true } } },
    orderBy: [{ start_date: 'asc' }, { id: 'asc' }],
  })
  return rows
    .map((row) => ({ ...serializeLease(row), unitName: row.units.name, tenantName: row.tenants.full_name }))
    .sort((a, b) => (a.unitName === b.unitName ? 0 : a.unitName < b.unitName ? -1 : 1))
}
import { z } from 'zod'
import { parseInstantWithOffset } from '@/lib/dates'
import { badRequest, notFound, withRetry } from '@/lib/errors'
import { prisma } from '@/lib/prisma'
import { createAdminClient } from '@/lib/supabase/admin-client'
import { isUuid, loadCaller, requireLeaseAccess, requirePaymentAccess, type Caller } from '@/server/access'
import { asPaymentStatus, type PaymentStatus, type ServiceCtx } from './serialize'

const SLIP_BUCKET = 'payment-slips'
const SLIP_URL_TTL_SECONDS = 60
const REASON_MESSAGE = 'Reason must be at least 5 characters'
const RECEIVED_AT_MESSAGE = 'receivedAt must be an ISO 8601 instant with an offset'

const recordPaymentSchema = z
  .object({
    // zod 4: .int() already rejects values outside the safe integer range (D3).
    amountSen: z.number().int().positive(),
    method: z.enum(['cash', 'bank_transfer']),
    receivedAt: z.string(),
    slipPath: z.string().min(1).max(512).optional(),
  })
  .strict()

const reasonSchema = z
  .object({
    reason: z.string().trim().min(5, REASON_MESSAGE),
  })
  .strict()

export type RecordPaymentInput = z.infer<typeof recordPaymentSchema>
export type RecordPaymentResult = { id: string; status: PaymentStatus; replayed: boolean }

type RecordPaymentRow = { id: string; status: string; replayed: boolean }
type StatusRow = { status: string }

// Each private.* money function returns exactly one row; anything else means the schema drifted (500).
function single<T>(rows: T[]): T {
  if (rows.length !== 1) throw new Error('Expected exactly one row from a money function')
  return rows[0]
}

// R44/D22: a slip may only live in the lease's own org folder; '..' or a leading '/' never reaches Storage.
function isOwnOrgSlipPath(path: string, orgId: string): boolean {
  return path.startsWith(`${orgId}/`) && !path.includes('..') && !path.includes('\\') && path.length > orgId.length + 1
}

// R20: "If recording fails after the upload, the file must not be left behind." Only an object in the
// lease's org folder that no payment references is removed, so a failed request can never delete another
// org's file or a slip that already backs a payment (e.g. a 409 replay with a different payload).
async function removeOrphanSlip(path: string, orgId: string): Promise<void> {
  if (!isOwnOrgSlipPath(path, orgId)) return
  try {
    const referenced = await prisma.payments.findFirst({ where: { org_id: orgId, slip_path: path }, select: { id: true } })
    if (referenced) return
    const { error } = await createAdminClient().storage.from(SLIP_BUCKET).remove([path])
    if (error) console.error('[payments] slip cleanup failed', { name: error.name })
  } catch (e) {
    // Cleanup must never mask the original error; log the class only (no paths or payloads).
    console.error('[payments] slip cleanup failed', { name: e instanceof Error ? e.name : typeof e })
  }
}

async function requireRecorder(caller: Caller, leaseId: string): Promise<{ orgId: string; leaseId: string }> {
  // R1/R38: staff/manager of the lease's org; the lease's tenant -> 403; anyone else -> 404.
  const lease = await requireLeaseAccess(caller, leaseId, ['manager', 'staff'])
  return { orgId: lease.org_id, leaseId: lease.id }
}

// Error contract order for POST /api/leases/:leaseId/payments: the route calls this before reading the
// body, so 404/403 win over a malformed-JSON 400. recordPayment repeats the check, so it is safe alone.
export async function authorizeRecordPayment(ctx: ServiceCtx, leaseId: string): Promise<void> {
  await requireRecorder(await loadCaller(ctx.userId), leaseId)
}

// Same pre-check for approve / reject / void (manager of the payment's org; staff of it -> 403).
export async function authorizePaymentDecision(ctx: ServiceCtx, paymentId: string): Promise<void> {
  await requirePaymentAccess(await loadCaller(ctx.userId), paymentId, ['manager'])
}

export async function recordPayment(
  ctx: ServiceCtx,
  leaseId: string,
  input: unknown,
  opts?: { idempotencyKey?: string },
): Promise<RecordPaymentResult> {
  const caller = await loadCaller(ctx.userId)
  // Read before validation so a slip uploaded for a request that fails any later check is still cleaned up.
  const rawSlip =
    typeof input === 'object' && input !== null && 'slipPath' in input && typeof input.slipPath === 'string'
      ? input.slipPath
      : null

  try {
    // Authorization sits inside the cleanup try: a 404/403 on the lease must not leave the uploaded slip behind.
    const { orgId, leaseId: checkedLeaseId } = await requireRecorder(caller, leaseId)

    const key = opts?.idempotencyKey
    // D9: the key is optional (the brief's body has none) but must be a uuid when sent.
    if (key !== undefined && !isUuid(key)) throw badRequest('Idempotency-Key must be a UUID')

    const body = recordPaymentSchema.parse(input)

    let receivedAt: Date
    try {
      // D6: a naive date-time is ambiguous; only Z or an explicit offset is accepted.
      receivedAt = parseInstantWithOffset(body.receivedAt)
    } catch {
      throw badRequest(RECEIVED_AT_MESSAGE)
    }

    const slipPath = body.slipPath ?? null
    if (body.method === 'bank_transfer' && slipPath === null) throw badRequest('A bank transfer needs a slip')
    if (body.method === 'cash' && slipPath !== null) throw badRequest('A cash payment cannot have a slip')
    // R44/D22: record_payment re-checks that the object exists in storage.objects under this org.
    if (slipPath !== null && !isOwnOrgSlipPath(slipPath, orgId)) throw badRequest('Slip file not found')

    // D7/D9: one plpgsql call does lock -> replay check -> validation -> cap -> insert -> allocate in a
    // single transaction; withRetry covers one serialization failure / deadlock, then 409.
    const row = single(
      await withRetry(() =>
        prisma.$queryRaw<RecordPaymentRow[]>`
          select r.id::text as id, r.status, r.replayed
          from private.record_payment(
            ${caller.userId}::uuid,
            ${checkedLeaseId}::uuid,
            ${body.amountSen}::bigint,
            ${body.method}::text,
            ${receivedAt.toISOString()}::timestamptz,
            ${slipPath}::text,
            ${key ?? null}::uuid
          ) r`,
      ),
    )
    return { id: row.id, status: asPaymentStatus(row.status), replayed: row.replayed }
  } catch (e) {
    // Delete only inside the caller's own org folder, never the (possibly unrelated) lease's org (R20/R44).
    if (rawSlip !== null && caller.member) await removeOrphanSlip(rawSlip, caller.member.orgId)
    throw e
  }
}

export async function approvePayment(ctx: ServiceCtx, paymentId: string): Promise<{ status: PaymentStatus }> {
  const caller = await loadCaller(ctx.userId)
  const payment = await requirePaymentAccess(caller, paymentId, ['manager'])
  // D7/R28: approve_payment locks lease then payment and re-reads status, so a double approve allocates once.
  const row = single(
    await withRetry(() =>
      prisma.$queryRaw<StatusRow[]>`
        select r.status from private.approve_payment(${caller.userId}::uuid, ${payment.id}::uuid) r`,
    ),
  )
  return { status: asPaymentStatus(row.status) }
}

function parseReason(input: unknown): string {
  const parsed = reasonSchema.safeParse(input)
  if (parsed.success) return parsed.data.reason
  // R24: a missing, non-string or short reason gets the one fixed message; unknown keys keep zod's.
  if (parsed.error.issues.some((i) => i.path[0] === 'reason')) throw badRequest(REASON_MESSAGE)
  throw parsed.error
}

export async function rejectPayment(ctx: ServiceCtx, paymentId: string, input: unknown): Promise<{ status: PaymentStatus }> {
  const caller = await loadCaller(ctx.userId)
  const payment = await requirePaymentAccess(caller, paymentId, ['manager'])
  const reason = parseReason(input)
  const row = single(
    await withRetry(() =>
      prisma.$queryRaw<StatusRow[]>`
        select r.status from private.reject_payment(${caller.userId}::uuid, ${payment.id}::uuid, ${reason}::text) r`,
    ),
  )
  return { status: asPaymentStatus(row.status) }
}

export async function voidPayment(ctx: ServiceCtx, paymentId: string, input: unknown): Promise<{ status: PaymentStatus }> {
  const caller = await loadCaller(ctx.userId)
  const payment = await requirePaymentAccess(caller, paymentId, ['manager'])
  const reason = parseReason(input)
  // D14: void_payment removes only this payment's allocations; other payments are untouched.
  const row = single(
    await withRetry(() =>
      prisma.$queryRaw<StatusRow[]>`
        select r.status from private.void_payment(${caller.userId}::uuid, ${payment.id}::uuid, ${reason}::text) r`,
    ),
  )
  return { status: asPaymentStatus(row.status) }
}

// R44/D22: the signed URL is made for the slip_path stored on a payment the caller may see, never for a
// client-supplied path, and lives 60 seconds.
export async function getSlipUrl(ctx: ServiceCtx, paymentId: string): Promise<{ url: string }> {
  const caller = await loadCaller(ctx.userId)
  const payment = await requirePaymentAccess(caller, paymentId, ['manager', 'staff'])
  if (!payment.slip_path) throw notFound('Slip not found')
  const { data, error } = await createAdminClient().storage.from(SLIP_BUCKET).createSignedUrl(payment.slip_path, SLIP_URL_TTL_SECONDS)
  if (error || !data) {
    if (error && /not found/i.test(error.message)) throw notFound('Slip not found')
    throw new Error('Could not sign the slip URL')
  }
  return { url: data.signedUrl }
}
import { toMytDate } from '@/lib/billing'
import { isYearMonth } from '@/lib/dates'
import { badRequest } from '@/lib/errors'
import { toSen } from '@/lib/money'
import { prisma } from '@/lib/prisma'
import { loadCaller, requireMember } from '@/server/access'
import { isoDateToDb, paidByInvoice, serializeInvoice, type ServiceCtx } from './serialize'

const MAX_MONTHS = 120

export type CollectionsRow = { month: string; collectedSen: number }

function monthIndex(ym: string): number {
  return Number(ym.slice(0, 4)) * 12 + Number(ym.slice(5, 7)) - 1
}

// GET /api/reports/collections: approved payments summed per Malaysia calendar month of received_at.
export async function collectionsReport(ctx: ServiceCtx, from: string, to: string): Promise<CollectionsRow[]> {
  const caller = await loadCaller(ctx.userId)
  const { orgId } = requireMember(caller, ['manager', 'staff'])
  // Bounded so one request cannot ask Postgres for an arbitrarily long series.
  if (!isYearMonth(from) || !isYearMonth(to) || from > to || monthIndex(to) - monthIndex(from) + 1 > MAX_MONTHS) {
    throw badRequest('Invalid range')
  }
  // D25: generate_series gives every month in [from, to] so empty months appear as 0 (brief R29). The
  // series is built on timestamp WITHOUT time zone, so the session TimeZone never shifts a month. A
  // payment's month is its received_at in Asia/Kuala_Lumpur (R3), not UTC: 2026-03-01 00:30 MYT is March.
  // sum(bigint) is numeric, cast back to bigint; toSen turns it into a safe JS number (D3).
  const rows = await prisma.$queryRaw<{ month: string; collected_sen: bigint }[]>`
    with months as (
      select generate_series(
        to_date(${from}, 'YYYY-MM')::timestamp,
        to_date(${to}, 'YYYY-MM')::timestamp,
        interval '1 month'
      ) as m
    ),
    collected as (
      select to_char(p.received_at at time zone 'Asia/Kuala_Lumpur', 'YYYY-MM') as month,
             sum(p.amount_sen) as total
      from public.payments p
      where p.org_id = ${orgId}::uuid
        and p.status = 'approved'
      group by 1
    )
    select to_char(months.m, 'YYYY-MM') as month,
           coalesce(collected.total, 0)::bigint as collected_sen
    from months
    left join collected on collected.month = to_char(months.m, 'YYYY-MM')
    order by months.m`
  return rows.map((r) => ({ month: r.month, collectedSen: toSen(r.collected_sen) }))
}

// Dashboard: number of the org's invoices whose computed status (billing.ts, R27) is overdue at asOf.
export async function overdueCount(ctx: ServiceCtx, asOf: Date): Promise<number> {
  const caller = await loadCaller(ctx.userId)
  const { orgId } = requireMember(caller, ['manager', 'staff'])
  // Prefilter only (an invoice cannot be overdue before its due date has passed in MYT, D5); the
  // decision itself is invoiceStatus, so there is a single definition of overdue.
  const candidates = await prisma.invoices.findMany({
    where: { org_id: orgId, due_date: { lt: isoDateToDb(toMytDate(asOf)) } },
  })
  if (candidates.length === 0) return 0
  const sums = await prisma.payment_allocations.groupBy({
    by: ['invoice_id'],
    where: { org_id: orgId, invoice_id: { in: candidates.map((c) => c.id) } },
    _sum: { amount_sen: true },
  })
  const paid = paidByInvoice(sums)
  return candidates.filter((row) => serializeInvoice(row, paid.get(row.id) ?? 0, asOf).status === 'overdue').length
}

